<?php
$pageTitle='Data RFID';
$pageSubtitle='Kelola UID KTM, e-KTP, kartu tamu, dan kartu khusus untuk validasi akses parkir.';
require_once __DIR__ . '/includes/header.php';
$action=$_POST['action'] ?? $_GET['action'] ?? '';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $id_user=($_POST['id_user']??'')!==''?(int)$_POST['id_user']:null;$uid=strtoupper(trim($_POST['uid_kartu']??''));$label=trim($_POST['label_kartu']??'');$jenis=$_POST['jenis_kartu']??'KTM';$status=(int)($_POST['status_kartu']??1);$tgl=$_POST['tanggal_daftar']??date('Y-m-d');$exp=trim($_POST['expired_at']??'')?:null;
    try{
        if($action==='create'){$pdo->prepare('INSERT INTO rfid_cards (id_user,uid_kartu,label_kartu,jenis_kartu,status_kartu,tanggal_daftar,expired_at) VALUES (?,?,?,?,?,?,?)')->execute([$id_user,$uid,$label,$jenis,$status,$tgl,$exp]);flash('success','Kartu RFID berhasil ditambahkan.');}
        if($action==='update'){$pdo->prepare('UPDATE rfid_cards SET id_user=?, uid_kartu=?, label_kartu=?, jenis_kartu=?, status_kartu=?, tanggal_daftar=?, expired_at=? WHERE id_rfid=?')->execute([$id_user,$uid,$label,$jenis,$status,$tgl,$exp,(int)$_POST['id_rfid']]);flash('success','Kartu RFID berhasil diperbarui.');}
    }catch(Exception $e){flash('danger','Gagal menyimpan. UID kartu sudah terdaftar atau data tidak valid.');}
    redirect('rfid_cards.php');
}
if($action==='delete'){$pdo->prepare('DELETE FROM rfid_cards WHERE id_rfid=?')->execute([(int)$_GET['id']]);flash('success','Kartu RFID berhasil dihapus.');redirect('rfid_cards.php');}
$users=$pdo->query('SELECT id_user,kode_user,nama_user FROM users ORDER BY nama_user')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM rfid_cards WHERE id_rfid=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$q=trim($_GET['q']??'');$like="%$q%";
$stmt=$pdo->prepare('SELECT r.*,u.nama_user,u.kode_user,u.jenis_user FROM rfid_cards r LEFT JOIN users u ON u.id_user=r.id_user WHERE r.uid_kartu LIKE ? OR r.label_kartu LIKE ? OR u.nama_user LIKE ? ORDER BY r.id_rfid DESC');$stmt->execute([$like,$like,$like]);$rows=$stmt->fetchAll();
?>
<div class="grid grid-2">
<div class="card"><div class="card-title"><h3><?= $edit?'Edit RFID':'Tambah RFID' ?></h3></div><form method="post"><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id_rfid" value="<?= $edit['id_rfid'] ?>"><?php endif; ?><div class="form-grid"><div class="form-group"><label>UID Kartu</label><input class="input" name="uid_kartu" value="<?= e($edit['uid_kartu']??'') ?>" placeholder="Contoh: 04A1B2C3D4" required></div><div class="form-group"><label>Label Kartu</label><input class="input" name="label_kartu" value="<?= e($edit['label_kartu']??'') ?>" placeholder="KTM Nama Pengguna"></div><div class="form-group"><label>Terhubung Pengguna</label><select class="select" name="id_user"><option value="">Belum dihubungkan</option><?php foreach($users as $u): ?><option value="<?= $u['id_user'] ?>" <?= ($edit['id_user']??'')==$u['id_user']?'selected':'' ?>><?= e($u['kode_user'].' - '.$u['nama_user']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Jenis Kartu</label><select class="select" name="jenis_kartu"><?php foreach(['KTM','e-KTP','Kartu Tamu','Kartu Khusus'] as $j): ?><option <?= ($edit['jenis_kartu']??'')==$j?'selected':'' ?>><?= $j ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Tanggal Daftar</label><input class="input" type="date" name="tanggal_daftar" value="<?= e($edit['tanggal_daftar']??date('Y-m-d')) ?>"></div><div class="form-group"><label>Berlaku Sampai</label><input class="input" type="date" name="expired_at" value="<?= e($edit['expired_at']??'') ?>"></div><div class="form-group"><label>Status</label><select class="select" name="status_kartu"><option value="1" <?= ($edit['status_kartu']??1)==1?'selected':'' ?>>Aktif</option><option value="0" <?= ($edit['status_kartu']??1)==0?'selected':'' ?>>Nonaktif</option></select></div></div><div class="form-actions"><button class="btn btn-primary">Simpan</button><?php if($edit): ?><a class="btn btn-light" href="rfid_cards.php">Batal Edit</a><?php endif; ?></div></form></div>
<div class="card"><div class="card-title"><h3>Format API RFID</h3></div><p>ESP32/ESP8266 mengirim UID ke endpoint berikut.</p><div class="alert alert-info"><b>GET</b> /api/scan.php?uid=04A1B2C3D4&gate_id=1&area_id=1</div><p>Respons JSON berisi status akses dan instruksi servo.</p></div>
</div>
<div class="card" style="margin-top:18px"><div class="toolbar"><h3 style="margin:0">Daftar Kartu RFID</h3><form class="search-form"><input class="input" name="q" value="<?= e($q) ?>" placeholder="Cari UID/label/pengguna"><button class="btn btn-light">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>UID</th><th>Label</th><th>Pengguna</th><th>Jenis</th><th>Berlaku</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= e($r['uid_kartu']) ?></b></td><td><?= e($r['label_kartu']) ?></td><td><?= e($r['nama_user']?:'-') ?><br><small><?= e($r['kode_user']?:'-') ?></small></td><td><?= e($r['jenis_kartu']) ?></td><td><?= e($r['tanggal_daftar']) ?> s.d <?= e($r['expired_at']?:'Tidak dibatasi') ?></td><td><span class="badge <?= $r['status_kartu']?'badge-success':'badge-danger' ?>"><?= $r['status_kartu']?'Aktif':'Nonaktif' ?></span></td><td><a class="btn btn-warning btn-sm" href="rfid_cards.php?edit=<?= $r['id_rfid'] ?>">Edit</a> <a class="btn btn-danger btn-sm" data-confirm="Hapus kartu ini?" href="rfid_cards.php?action=delete&id=<?= $r['id_rfid'] ?>">Hapus</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="7" class="empty">Data RFID belum tersedia.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require_once __DIR__ . '/includes/footer.php'; ?>
